<template>
  <div class="page">
    <div class="order-manage__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>订单管理</h3>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="orderNo" label="订单号" min-width="160" />
            <el-table-column prop="goods" label="商品" min-width="180" />
            <el-table-column prop="amount" label="金额" min-width="120" />
            <el-table-column prop="user" label="买家" min-width="150" />
            <el-table-column prop="tag" label="状态" min-width="110">
              <template #default="scope">
                <el-tag :type="tagType(scope.row.tag)" disable-transitions>{{ scope.row.tag }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createtime" label="下单时间" min-width="180" />
            <el-table-column label="操作" min-width="140">
              <template #default="scope">
                <el-button
                  v-if="scope.row.tag === '待发货'"
                  size="small"
                  type="primary"
                  @click="handleShip(scope.row.orderNo)"
                >
                  发货
                </el-button>
                <el-button v-else size="small" @click="handleView(scope.row)">查看</el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="order-manage__pagination-wrap">
        <div class="totalnum">
          <h3>订单统计</h3>
          <p>当前共 {{ tableData.length }} 笔订单</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'

const currentPage = ref(1)
const pageSize = ref(6)

const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})

const tagType = (tag) => {
  const map = {
    '待付款': 'warning',
    '待发货': 'primary',
    '已发货': 'info',
    '已完成': 'success',
    '已取消': 'danger',
  }
  return map[tag] || 'info'
}

const handleShip = (orderNo) => {
  const row = tableData.value.find((item) => item.orderNo === orderNo)
  if (!row) return
  row.tag = '已发货'
  ElMessage.success(`订单 ${orderNo} 已发货`)
}

const handleView = (row) => {
  ElMessageBox.alert(
    `订单号：${row.orderNo}\n商品：${row.goods}\n金额：${row.amount}\n买家：${row.user}`,
    '订单详情',
    { confirmButtonText: '确定' }
  )
}

